#!/usr/bin/env python3
"""Проверки исходников, роспера и технической документации."""

from __future__ import annotations

import argparse
import codecs
import re
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
SRC = ROOT / "src"
DOCS = ROOT / "docs"
DEVNOTES = ROOT / "DEVNOTES.md"
ROSTER_START = "<!-- ROSTER:START -->"
ROSTER_END = "<!-- ROSTER:END -->"
VALID_COMBO = set("DURLPK")
VALID_ARENA = set(range(10))
FORBIDDEN_MARKERS = (
    "generated by",
    "written by ai",
    "chatgpt",
    "openai",
    "assistant",
)
SERVICE_FILES = {"AGENTS.md"}


def fail(message: str, errors: list[str]) -> None:
    errors.append(message)


def read_text(path: Path) -> str:
    try:
        return path.read_text(encoding="utf-8")
    except UnicodeDecodeError as exc:
        raise SystemExit(f"UTF-8 error in {path.relative_to(ROOT)}: {exc}") from exc


def js_sources() -> list[Path]:
    return sorted(
        path for path in SRC.rglob("*.js")
        if path.is_file() and "legacy" not in path.parts
    )


def roster_source() -> str:
    path = SRC / "data" / "characters.js"
    if path.exists():
        return read_text(path)
    legacy = SRC / "legacy" / "karnage.js"
    if legacy.exists():
        return read_text(legacy)
    return "\n".join(read_text(item) for item in js_sources())


def parse_roster(text: str) -> list[dict[str, object]]:
    base = re.search(r"const CH\s*=\s*\[(.*?)\];", text, re.S)
    if not base:
        return []
    blocks = re.findall(r"\{id:(\d+),([^{}]*)\}", base.group(1))
    rows: list[dict[str, object]] = []
    for raw_id, body in blocks:
        row: dict[str, object] = {"id": int(raw_id)}
        for field in ("name", "en", "spec", "fat", "arena"):
            match = re.search(rf"\b{field}:('([^']*)'|\d+)", body)
            if match:
                value = match.group(1)
                row[field] = int(value) if value.isdigit() else value.strip("'")
        rows.append(row)
    for raw_id, body in re.findall(r"CH\.push\(\{id:(\d+),([^{}]*)\}\)", text):
        row: dict[str, object] = {"id": int(raw_id)}
        for field in ("name", "en", "spec", "fat", "arena"):
            match = re.search(rf"\b{field}:('([^']*)'|\d+)", body)
            if match:
                value = match.group(1)
                row[field] = int(value) if value.isdigit() else value.strip("'")
        rows.append(row)
    spec2 = {int(i): value for i, value in re.findall(r"CH\[(\d+)\]\.spec2='([DURLPK]+)'", text)}
    for row in rows:
        row["spec2"] = spec2.get(int(row["id"]), "")
    rows.sort(key=lambda row: int(row["id"]))
    return rows


def roster_table(rows: list[dict[str, object]]) -> str:
    lines = [
        "| id | key | имя | spec | spec2 | fat | arena |",
        "|---:|---|---|---|---|---|---:|",
    ]
    for row in rows:
        lines.append(
            "| {id} | {en} | {name} | {spec} | {spec2} | {fat} | {arena} |".format(**row)
        )
    return "\n".join(lines)


def check_roster(rows: list[dict[str, object]], errors: list[str]) -> None:
    if not rows:
        fail("roster: CH not found", errors)
        return
    ids = [int(row["id"]) for row in rows]
    if ids != list(range(len(rows))):
        fail(f"roster: ids are not sequential: {ids}", errors)
    for row in rows:
        rid = row["id"]
        for field in ("spec", "spec2", "fat"):
            combo = str(row.get(field, ""))
            if not combo or set(combo) - VALID_COMBO:
                fail(f"roster {rid}: invalid {field} {combo!r}", errors)
        if not str(row.get("fat", "")).endswith(("P", "K")):
            fail(f"roster {rid}: fatality must end with P or K", errors)
        if row.get("arena") not in VALID_ARENA:
            fail(f"roster {rid}: invalid arena {row.get('arena')!r}", errors)
        if row.get("spec") == row.get("spec2"):
            fail(f"roster {rid}: spec and spec2 are identical", errors)


def check_comments(path: Path, text: str, warnings: list[str]) -> None:
    pattern = re.compile(r"//.*?[^\s:](?:if\(|for\(|while\(|return\s|const\s|let\s|var\s|\}\))")
    for number, line in enumerate(text.splitlines(), 1):
        comment = line.find("//")
        if comment < 0:
            continue
        tail = line[comment + 2 :]
        if "http://" in line or "https://" in line:
            continue
        if pattern.search("//" + tail):
            warnings.append(f"{path.relative_to(ROOT)}:{number}: comment may contain code")


def check_service_files(errors: list[str]) -> None:
    skip = {"node_modules", ".git", "release", "test-results", "vendor"}
    for path in ROOT.rglob("*"):
        if any(part in skip for part in path.parts):
            continue
        if path.name in SERVICE_FILES:
            fail(f"service file must not be present: {path.relative_to(ROOT)}", errors)


def check_markers(errors: list[str]) -> None:
    if not DEVNOTES.exists():
        fail("DEVNOTES.md: missing", errors)
        return
    text = read_text(DEVNOTES)
    if ROSTER_START not in text or ROSTER_END not in text:
        fail("DEVNOTES.md: roster markers not found", errors)


def write_roster(rows: list[dict[str, object]]) -> None:
    text = read_text(DEVNOTES)
    table = roster_table(rows)
    start = text.index(ROSTER_START) + len(ROSTER_START)
    end = text.index(ROSTER_END)
    updated = text[:start] + "\n" + table + "\n" + text[end:]
    DEVNOTES.write_text(updated, encoding="utf-8")
    print("audit: roster table updated")


def check_roster_doc(rows: list[dict[str, object]], errors: list[str]) -> None:
    if not DEVNOTES.exists():
        return
    text = read_text(DEVNOTES)
    if ROSTER_START not in text or ROSTER_END not in text:
        return
    start = text.index(ROSTER_START) + len(ROSTER_START)
    end = text.index(ROSTER_END)
    current = text[start:end].strip()
    expected = roster_table(rows).strip()
    if current != expected:
        fail("DEVNOTES.md: roster table is stale; run audit.py --write-roster", errors)


TEXT_SUFFIXES = {".js", ".mjs", ".json", ".md", ".html", ".css", ".txt", ".py", ".yml", ".yaml"}
TEXT_NAMES = {".gitignore", ".gitattributes", ".editorconfig"}


def text_files() -> list[Path]:
    skip = {"node_modules", ".git", "test-results", "vendor"}
    out: list[Path] = []
    for path in ROOT.rglob("*"):
        if any(part in skip for part in path.parts):
            continue
        if not path.is_file():
            continue
        if path.suffix.lower() in TEXT_SUFFIXES or path.name in TEXT_NAMES:
            out.append(path)
    return sorted(out)


def check_encoding(errors: list[str]) -> None:
    for path in text_files():
        raw = path.read_bytes()
        if raw.startswith(codecs.BOM_UTF8):
            fail(f"{path.relative_to(ROOT)}: UTF-8 BOM is not allowed", errors)
            continue
        if raw.startswith(codecs.BOM_UTF16_LE) or raw.startswith(codecs.BOM_UTF16_BE):
            fail(f"{path.relative_to(ROOT)}: UTF-16 is not allowed", errors)
            continue
        if b"\x00" in raw:
            fail(f"{path.relative_to(ROOT)}: NUL byte in text file", errors)
            continue
        try:
            text = raw.decode("utf-8")
        except UnicodeDecodeError as exc:
            fail(f"{path.relative_to(ROOT)}: invalid UTF-8: {exc}", errors)
            continue
        if "\ufffd" in text:
            fail(f"{path.relative_to(ROOT)}: replacement character in text", errors)


def fix_bom(errors: list[str]) -> None:
    for path in text_files():
        raw = path.read_bytes()
        if raw.startswith(codecs.BOM_UTF8):
            path.write_bytes(raw[len(codecs.BOM_UTF8):])
            print(f"audit: removed UTF-8 BOM from {path.relative_to(ROOT)}")
        elif raw.startswith(codecs.BOM_UTF16_LE) or raw.startswith(codecs.BOM_UTF16_BE):
            fail(f"{path.relative_to(ROOT)}: UTF-16 must be converted manually", errors)


def check_fx_assets(errors: list[str]) -> None:
    import json

    manifest = ROOT / "assets" / "fx" / "fx.json"
    if not manifest.exists():
        return
    try:
        data = json.loads(read_text(manifest))
    except json.JSONDecodeError as exc:
        fail(f"assets/fx/fx.json: {exc}", errors)
        return
    for key, definition in data.items():
        path = manifest.parent / definition.get("image", "")
        if not path.exists() or path.stat().st_size == 0:
            fail(f"assets/fx: missing image for {key}", errors)
    for vendor in (ROOT / "assets" / "vendor").iterdir():
        if not vendor.is_dir():
            continue
        for name in ("LICENSE.txt", "SOURCE.md"):
            if not (vendor / name).exists():
                fail(f"assets/vendor/{vendor.name}: missing {name}", errors)


def check_archive_checksums(errors: list[str]) -> None:
    import hashlib

    for sums in sorted((ROOT / "archive").rglob("SHA256SUMS.txt")):
        base = sums.parent
        for line in read_text(sums).splitlines():
            if not line.strip():
                continue
            digest, rel = line.split("  ", 1)
            path = base / rel
            if not path.exists():
                fail(f"{sums.relative_to(ROOT)}: missing {rel}", errors)
                continue
            actual = hashlib.sha256(path.read_bytes()).hexdigest()
            if actual != digest:
                fail(f"{sums.relative_to(ROOT)}: checksum mismatch for {rel}", errors)


def check_assets(errors: list[str]) -> None:
    css = ROOT / "assets" / "styles" / "main.css"
    if not css.exists():
        fail("assets/styles/main.css: missing", errors)
        return
    for match in re.findall(r"url\('([^']+)'\)", read_text(css)):
        if match.startswith(("http://", "https://", "data:")):
            continue
        if not (css.parent / match).resolve().exists():
            fail(f"assets/styles/main.css: missing asset {match}", errors)
    dev = ROOT / "dev.html"
    if not dev.exists():
        fail("dev.html: missing", errors)
    elif "./src/main.js" not in read_text(dev):
        fail("dev.html: module entry not found", errors)
    index = ROOT / "index.html"
    if not index.exists():
        fail("index.html: missing", errors)
    elif "./release/app.js" not in read_text(index):
        fail("index.html: release entry not found", errors)


def check_forbidden(errors: list[str]) -> None:
    for path in list(SRC.rglob("*.js")) + list(DOCS.rglob("*.md")) + [ROOT / "README.md", DEVNOTES]:
        if not path.exists():
            continue
        text = read_text(path).lower()
        for marker in FORBIDDEN_MARKERS:
            if marker in text:
                fail(f"{path.relative_to(ROOT)}: forbidden marker {marker!r}", errors)


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--check", action="store_true", help="run checks")
    parser.add_argument("--write-roster", action="store_true", help="update roster table in DEVNOTES")
    parser.add_argument("--fix-bom", action="store_true", help="strip UTF-8 BOM from text files")
    args = parser.parse_args()
    if not args.check and not args.write_roster:
        args.check = True

    errors: list[str] = []
    warnings: list[str] = []
    rows = parse_roster(roster_source())

    if args.write_roster:
        write_roster(rows)
    if args.fix_bom:
        fix_bom(errors)

    if args.check:
        check_encoding(errors)
        check_roster(rows, errors)
        check_markers(errors)
        check_roster_doc(rows, errors)
        check_assets(errors)
        check_fx_assets(errors)
        check_archive_checksums(errors)
        check_service_files(errors)
        check_forbidden(errors)
        for path in js_sources():
            check_comments(path, read_text(path), warnings)

    for warning in warnings:
        print(f"warning: {warning}")
    if errors:
        for error in errors:
            print(f"error: {error}")
        return 1
    print(f"audit: {len(rows)} fighters, {len(warnings)} warning(s)")
    return 0


if __name__ == "__main__":
    if hasattr(sys.stdout, "reconfigure"):
        sys.stdout.reconfigure(encoding="utf-8")
    raise SystemExit(main())
